There are two matrices, before[][] and after[][] of size N×M. The matrix after[][] is obtained by applying the 2D prefix sum operation on before[][]. Given the matrix after[][], reconstruct the original matrix before[][].Examples:Input:  after[][] = [ [1, 3, 6], [3, 7, 11] ]Output:1 2 32 2 1Explanation: The before matrix for the given after matrix is [ [1, 2, 3], [2, 2, 1] ].Because according to the code given in problem, after(0, 0) = before(0, 0) = 1after(0, 1) = before(0, 0) + before(0, 1) = 1 + 2 = 3.after(0, 2) = before(0, 0) + before(0, 1) + before(0, 2) = 1 + 2 + 3 = 6.after(1, 0) = before(0, 0) + before(1, 0) = 1 + 2 = 3;, after(1, 1) = before(0, 0) + before(0, 1) + before(1, 0) + before(1, 1) = 1 + 2 + 2 + 2 = 7.after(1, 2) = before(0, 0) + before(0, 1) + before(0, 2) + before(1, 0) + before(1, 1) + before(1, 2) = 1 + 2 + 3 + 2 + 2 + 1 = 11Input: after[][] = [[1, 3, 5]]Output:1 2 2Try It YourselfReconstruct the Matrix from 2D Prefix Sum O(n × m ) time and O(n × m ) spaceConsider the opposite task, i.e. to convert before[][] matrix to after[][]. As seen from the problem statement, after[i][j] is the summation of all the cells to the left of jth column and all the rows above the ith row. That is basically the prefix sum of a matrix.  So this problem is mainly an extension of  Original Array from given Prefix SumsUsing the 2D prefix sum formula: prefix[i][j] = arr[i][j] + prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1]Rearranging the equation, we get: arr[i][j] = prefix[i][j] - prefix[i-1][j] - prefix[i][j-1] + prefix[i-1][j-1]
            C++

    //Driver Code Starts
#include<iostream>
#include<vector>
using namespace std;

//Driver Code Ends

vector<vector<int>> computeBeforeMatrix(vector<vector<int>>& after) {
    int n = after.size(), m = after[0].size();

    // Declaring a 2d array to store
    // the values of the before Matrix
    vector<vector<int>> before(n, vector<int>(m, 0));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (i == 0 && j == 0)
                before[0][0] = after[0][0];
            else if (i == 0)
                before[i][j]
                    = after[i][j] - after[i][j - 1];
            else if (j == 0)
                before[i][j]
                    = after[i][j] - after[i - 1][j];
            else
                before[i][j]
                    = after[i][j] + after[i - 1][j - 1]
                      - after[i - 1][j] - after[i][j - 1];
        }
    }

    return before;
}

//Driver Code Starts

int main() {
    vector<vector<int>> after{ {1, 3, 6 }, { 3, 7, 11 } };

    vector<vector<int>> ans = computeBeforeMatrix(after);
    for (auto u : ans) {
        for (int x : u)
            cout << x << " ";
        cout << endl;
    }
    return 0;
}
